      "summary": "그룹 슈퍼주니어 멤버 신동이 자신이 겪어온 다이어트 경험을 털어놓으며 \"비만 유전자는 확실히 있다\"고 주장해 눈길을 끌었다. 지난 25일 채널A 공식 SNS에는 '전현무계획4'에 출연한 신동 전현무 곽준빈이 대화를 나누는 모습이 공개됐다. '물만 마셔도 살 찌는 과학적 근거'라는 제목의 영상에서 곽준빈은 신동에게 \"살이 쪘을 때 가장 큰 원인이 뭐였냐\"라고 질문했다. 이에 신동은 \"내가 이건 솔직히 얘기할 수 있다. '비만 유전자'는 확실히 있다\"며 요요 현상을 여러 차례 겪었던 자신의 경험을 바탕으로 체질의 영향을 강조했다. 이어 그는 \"우리 셋이 똑같이 먹어도 셋 중 누군가는 더 살이 찐다\"고 말하며 사람마다 체질이 다를 수 있다고 설명했다. 곽준빈이 \"우리 셋은 비슷하지 않냐\"고 되묻자 신동은 \"아니다. 내가 제일 셀 거다. 난 진짜 생각보다 진짜 안 먹는다\"고 답했다. 이를 듣던 전현무 역시 \"인정\"이라고 맞장구를 치며 신동의 평소 식사량에 공감하는 모습을 보여 웃음을 자아냈",
