      "summary": "배우 짧은 웨이브 헤어로 독특한 스타일을 선보이고 김지훈과 케미를 드러냈다. 김혜수는 최근 자신의 인스타그램에 '지금불륜이문제가아닙니다'를 홍보하는 멘트를 남기며 사진을 올렸다. 공개된 사진 속 김혜수는 헤어 도구와 거울이 놓인 대기 공간에서 정면을 바라보며 부드럽게 미소 짓고 있다. 짧고 풍성한 브라운 웨이브 헤어가 얼굴선을 감쌌으며, 블루와 브라운을 중심으로 옐로와 오렌지 컬러가 섞인 스트라이프 니트가 강렬한 인상을 남겼다. 전신을 드러낸 김혜수는 한 손을 배 위에 올린 채 카메라를 응시했다. 넉넉한 니트에 무릎까지 내려오는 오렌지 팬츠를 매치했으며 머스터드 컬러 양말과 검은색 슈즈가 다채로운 옷차림을 완성했다. 천장 조명과 헤어 도구가 놓인 이동식 수납장, 무늬가 들어간 바닥이 대기 공간의 모습을 구체적으로 보여줬다. 김지훈과 함께한 김혜수는 한 팔로 김지훈의 어깨를 감싸고 다른 손을 턱 아래에 펼친 채 카메라를 바라봤다. 김혜수의 짧은 브라운 웨이브 헤어와 김지훈의 위로 묶은",
