      "summary": "프랑스에서 작품성과 흥행성을 동시에 인정받은 화제의 심리극 ‘알테르 에고(Alter Ego(s))’가 오는 9월 한국에 상륙한다. 기억과 정체성, 인간 내면의 복합적인 자아를 깊이 있게 탐구하는 작품으로, 올가을 공연계 기대작으로 주목받고 있다. ‘알테르 에고’는 국내에서도 꾸준히 사랑받은 1인극 ‘온 더 비트(Une Vie Sur Mesure)’의 작가 겸 배우 쎄드릭 샤퓌가 마고 무트와 공동 집필한 작품이다. 2018년 프랑스 아비뇽 페스티벌에서 초연된 이후 관객과 평단의 호평을 받으며 꾸준히 무대에 오른 작품으로, 인간 심리를 섬세하게 파고드는 서사와 몰입도 높은 전개로 높은 평가를 받아왔다. 작품은 미국에서 가장 널리 알려진 해리성 정체감 장애(Dissociative Identity Disorder·DID) 사례인 빌리 밀리건의 삶에서 영감을 받아 탄생했다. 단순히 실화를 재현하는 데 머무르지 않고, 한 사람 안에 존재하는 여러 자아를 통해 인간의 정체성과 기억의 의미를 철학",
