      "summary": "배우 이수경이 새로 이사할 모든 시설이 완벽하게 갖춰진 새 보금자리를 최초 공개했다. 지난 23일 채널 '이수경력직'에는 '집 보러 왔다가 길 잃었어요. 수영장·골프장 딸린 수경의 새집 탐방'이라는 제목의 영상이 올라왔다. 이날 이수경은 새로운 보금자리를 공개하며 \"전세 만기가 됐는데 (지금 사는) 동네 주변이 너무 핫해지다 보니까 새로운 곳을 찾고 싶었다\"고 설명했다. 이어 \"이곳이 지인분들이 꽤 많이 산다. 다 같이 모여서 할 수 있는 것도 많고 아는 사람들이 있으니까 몸도 안전하고 필요할 때는 부탁할 수도 있어서 이쪽으로 오게됐다\"고 밝혔다. 또 새로 이사오게 될 집이 복합쇼핑몰 센터 위 오피스텔 구조라며 \"밖에 안 나가도 된다. 모든 게 한 곳에서 다 해결된다\"고 뿌듯해 하기도 했다. 이어 이수경은 공용 주방, 입주민 전용 공원, 인피니티 풀, 수영장 등 시설도 소개했다. 이에 감탄한 제작진이 \"관리비가 얼마 나올지 너무 궁금하다\"고 묻자 그는 \"나도 관리비 현타 오겠지만 열",
