      "summary": "그룹 코르티스(CORTIS)가 독보적인 MZ 감성 스타일링으로 ‘KMA 2026’ 레드카펫을 달궜다. 코르티스는 25일 서울 성북구 고려대학교 화정체육관에서 열린 ‘KMA 2026’ 시상식에 참석했다. 이날 마틴, 제임스, 주훈, 성현, 건호는 빈티지 무드와 워크웨어, 스포티즘을 결합한 Y2K 믹스매치 스타일을 선보이며 코르티스만의 개성을 드러냈다. 한편 ‘KMA 2026’은 지난 1년간 가요계를 빛낸 아티스트들과 이들을 응원해 온 팬들에게 헌정하는 음악 축제이자 시상식이다. 이날 시상식은 배우 강태오와 원지안이 MC를 맡았으며, 투모로우바이투게더, 피원하모니, 하이파이유니콘, 제로베이스원, 82메이저, 유니스, 비비업, 킥플립, 하츠투하츠, 뉴비트, 올데이 프로젝트, 코르티스, 알파드라이브원, 롱샷, 모디세이 등이 참석했다. 안암동(서울)=천정환 MK스포츠 기자",
