      "summary": "배우 하지원이 40대 후반이라는 나이가 믿기지 않는 스포티하고 매력적인 근황을 공유했다. 하지원은 26일 자신의 SNS를 통해 미국 워싱턴 D.C. 내셔널스 파크를 방문해 미국 프로야구 메이저리그(MLB) 경기를 관람한 일상이 담긴 사진 여러 장을 게시했다. 공개된 사진 속 하지원은 스트라이프 패턴의 튜브톱 상의에 빨간색 야구 모자를 쓰고 양 갈래로 땋은 헤어스타일을 연출해 상큼한 동안 미모를 과시했다. 시원하게 드러낸 쇄골 라인과 탄탄한 스포티룩이 어우러져 청순하면서도 발랄한 분위기를 더한다. 경기장 관중석에서 포즈를 취하는 모습부터 식당에서 브런치를 즐기는 모습까지, 여유로운 일상 속 독보적인 아우라가 시선을 사로잡는다. 하지원은 그간 국내 주요 경기는 물론 미국 메이저리그 무대에서도 성공적인 시구를 선보이며 큰 화제를 모은 바 있다. 최근에는 웹예능 ‘26학번 지원이요’ 등 다방면에서 기분 좋은 에너지를 전하며 신선한 매력을 선보였다. 또한 영화 ‘비광’ 개봉을 앞두고 있는 등",
