      "summary": "일본 인터뷰 도중 에스파 지젤이 남성 아나운서의 나이를 듣고 놀라움을 드러냈다. 노안 이미지와 달리 2001년생이라는 사실이 알려지면서 온라인에서도 화제를 모았다. 해당 인터뷰를 진행한 인물은 후지TV 소속 우에가키 코타로 아나운서다. 그는 인터뷰 중 자신의 나이를 밝혔고, 이를 들은 지젤은 깜짝 놀란 표정을 지으며 웃음을 터트렸다. 우에가키 코타로는 2001년 1월 6일생으로 효고현 출신이다. 오사카대학교 문학부를 졸업한 뒤 2024년 후지TV에 입사했으며, 차분한 정장 차림과 안경을 쓴 노안 이미지 때문에 실제 나이를 알게 된 누리꾼들은 \"생각보다 훨씬 어리다\", \"구르면서봐도 40대인데\", \"중년의 해설위원 아니냐\", \"가까이서 보니까 어리네 확실히\" 등의 반응을 보였다. 한편 2000생 지젤은 한일 혼혈인이다. 지젤은 에스파 멤버로 글로벌 활동을 이어가고 있다.",
