      "summary": "신인 시절, 유재석과 김종국의 뜻밖의 인연이 밝혀졌다. 7월 26일 tvN '유 퀴즈 온 더 블럭' 채널을 통해 공개된 예고편에서는 김종국과의 첫 만남을 회상하는 유재석의 모습이 담겼다. 해당 영상에서 유재석은 과거 터보의 팬미팅 MC를 봤었다고 말했다. 김종국은 \"나도 나중에 사진으로 알았다. 팬분이 예전에 재석이 형이 팬미팅 MC를 봤었다고 하는 거다. 그 분도 사진을 보고 알았다고 한다\"라 말했다. 그러자 유재석은 \"솔직히 이야기 하자면, 터보에 대한 애정보다는..\"이라면서 \"MC를 했으면 끝까지 팬미팅을 참여하고, 내가 하는 역할이 없더라도 노래까지 듣고 나오는 게 예의지만 돈 받는 순간 '여기까지다' 하고 신나게 갔다\"고 회상했다. 이에 김종국은 \"돈 받는 모습이 기억 난다. 흰 봉투를 받더니 90도 인사하더라\"고 유재석을 놀렸고, 유재석은 \"저에게는 큰 돈이었다. 잘 썼다\"고 반응해 웃음을 안겼다.",
