      "summary": "‘사랑이 온다’ 하석진이 안희연을 향한 직진 고백으로 첫사랑 로맨스의 막을 올렸다. 25일 방송된 KBS2 주말드라마 ‘사랑이 온다’(연출 홍석구, 극본 이경희) 1회에서는 김무진(하석진 분)이 한규림(안희연 분)과의 반복되는 우연 끝에 운명 같은 인연을 그려냈다. 시청률은 11.7%(닐슨 코리아 전국 기준)를 기록했다. 첫 회는 출근길 버스 정류장을 잘못 내린 김무진(하석진 분)이 한규림(안희연 분)과 우연히 마주치며 시작됐다. “커플 맞죠?”라는 아이의 질문에 시선을 돌린 김무진은 자신과 같은 옷을 입은 채 큐브를 맞추고 있는 한규림에게 호기심을 품게 됐다. 버스 출발 직전 한규림은 정류장 벤치에 쓰러진 박수남(강애심 분)을 발견하고 망설임 없이 발걸음을 옮겼다. 두 사람은 아르바이트 장소에서 뜻밖의 재회를 이뤘다. 진상 손님의 행동에 주먹을 쥐며 참아내던 김무진에게 한규림이 코코아 한 잔을 건넸다. 한규림은 “속상하고 화날 땐 달달한 코코아를 먹어요. 그리고 주문을 거는 거죠.",
