      "summary": "27일 오후 8시 30분 KBS2에서 방송되는 ‘다큐멘터리 3일’은 서울 홍대 홍익지구대의 72시간을 따라가며, 밤의 번화가를 지키는 경찰관들의 숨 가쁜 일상과 따뜻한 순간을 밀도 있게 담아낸다. 이번 731회 ‘미드나잇 인 홍대 - 마포 홍익지구대 72시간’ 편은 전국에서 가장 많은 112 신고가 접수되는 지구대의 3일을 기록한다. 분실물 신고부터 스토킹, 주취자 관련 사건·사고까지 끊임없이 이어지는 상황 속에서 경찰관들은 밤낮없이 현장을 누빈다. 프로그램은 단순한 현장 기록을 넘어 도시의 밤을 떠받치는 보이지 않는 노동을 정면으로 비춘다. 가장 인상적인 대목은 ‘홍대의 금요일 밤’을 버티는 사람들의 모습이다. 인파가 몰리고 과음한 주취자들이 하나둘 지구대로 들어오는 순간, 홍익지구대는 시민 안전의 최전선이자 밤새 주취자들을 보살피는 쉼 없는 공간으로 변한다. 미리 준비해 둔 매트리스가 빈자리를 찾기 어려울 만큼 쌓여가는 장면은 번화가의 화려함과 현장의 피로가 얼마나 극명하게 교차",
