      "summary": "영화 '스파이더맨: 브랜드 뉴 데이'의 사전 예매량이 50만 장을 돌파하며 강력한 흥행 신드롬을 예고했다. 26일 영화관입장권 통합전산망에 따르면 '스파이더맨: 브랜드 뉴 데이'는 이날 오전 10시 4분 기준 사전 예매관객수 50만 559명을 기록했다. 이는 2022년 개봉해 천만 관객을 동원한 '아바타: 물의 길'이 개봉 3일 전 오후 11시 기준 사전 예매관객수 50만 541명을 넘은 속도보다 빠른 결과다. 앞선 세 편의 '톰스파' 시리즈가 모두 700만 관객을 돌파한 만큼, '스파이더맨: 브랜드 뉴 데이'가 새롭게 써 내려갈 흥행 기록에 뜨거운 관심이 모아지고 있다. '스파이더맨: 브랜드 뉴 데이'는 지난 19일 전체 예매율 1위에 등극한 뒤, '톰스파' 3부작의 동시기 사전 예매량을 모두 뛰어넘으며 남다른 흥행 저력을 드러냈다. 이어 개봉 7일 전인 22일에는 올해 개봉작 가운데 가장 빠르게 사전 예매량 31만 장을 돌파했으며, 8일 연속 전체 예매율 1위의 자리를 굳건히 지",
