      "summary": "마블 영화 '스파이더맨: 브랜드 뉴 데이'가 개봉을 사흘 앞두고 사전 예매 관객수 50만 명을 돌파했다. 26일 영화관입장권 통합전산망에 따르면 이날 오전 1시 기준 '스파이더맨: 브랜드 뉴 데이'('스파이더맨4')의 예매 관객수는 51만 157명을 기록했다. 이는 올해 개봉작 중 개봉 3일 전 기준 최고 예매량이다. 2022년 천만 관객을 동원한 '아바타: 물의 길'이 개봉 3일 전 기록한 50만 541명을 넘어선 수치다. '스파이더맨4'는 마블 스튜디오의 스파이더맨 시리즈 네 번째 작품으로, 모두에게 잊힌 피터 파커가 소중한 이들을 지키기 위해 새로운 위협에 맞서는 액션 블록버스터다. 톰 홀랜드, 젠데이아 콜먼, 세이디 싱크, 제이콥 배덜런, 존 번탈 등이 출연한다. 오는 29일 국내 개봉한다.",
