      "summary": "천정부지로 치솟은 배우들의 출연료가 다시 도마 위에 올랐다. 정부가 배우 출연료를 일정 수준으로 제한하는 방안을 내놓으면서다. 현장에서는 취지에는 공감하면서도 실제 효과를 거둘 수 있을지에 대해서는 신중한 입장이다. 최근 문화체육관광부와 영화진흥위원회는 한국영화 제작 활성화를 위한 정부·제작사·매니지먼트사 간 협약을 체결했다. 협약식에는 문체부와 영진위를 비롯해 BH엔터테인먼트, 매니지먼트숲, 제이와이드컴퍼니 등 주요 매니지먼트사와 한국영화제작가협회, 한국영화프로듀서조합(PGK) 관계자들이 참석했다. 이번 협약은 정부가 지원하는 중예산 영화(순제작비 20억 원 이상~80억 원 미만)의 배우 출연료를 순제작비의 10% 미만으로 책정하는 것을 골자로 한다. 강제 규정보다는 자율적인 합의에 방점을 찍고 있다. 정부는 일회성에 그치지 않도록 자율 협의체를 구성해 제작 환경 개선 방안을 지속적으로 논의하기로 했다. 배우들의 출연료는 영화 제작 환경을 논할 때마다 빠지지 않는 고질적인 문제로",
