      "summary": "고레에다 히로카즈 감독이 연출과 각본, 편집을 맡은 실사 영화 <룩백>이 베니스국제영화제에서 고개된다. 고레에다 히로카즈 감독과 <체인소 맨> 후지모토 타츠키의 만남으로 주목받는 영화 <룩백>은 9월 이탈리아 베니스에서 열리는 제83회 베니스국제영화제 경쟁 부문에 공식 초청되었다. 고레에다 히로카즈 감독은 2018년 영화 <어느 가족>으로 칸국제영화제 최고상인 황금종려상을 수상한 거장이다. 최근에도 <브로커>(2022), <괴물>(2023), <상자 속의 양>(2026)으로 칸영화제에 연이어 초청되며 세계적인 명성을 이어가고 있다. 고레에다 감독에게 이번 베니스행은 7년 만의 방문이자 네 번째 경쟁 부문 진출로 더욱 눈길을 끈다. 실사 영화 <룩백>은 <극장판 체인소 맨: 레제편> 으로 글로벌 흥행 수입 297.8억 엔(국내 345만 관객)을 기록하며 세계적인 열풍을 일으킨 후지모토 타츠키의 동명 단편 만화를 원작으로 한다. 2024년 개봉한 애니메이션 <룩백>은 제48회 일본 아카",
