      "summary": "‘스파이더맨: 브랜드 뉴 데이’의 사전 예매량이 50만 장을 돌파했다. 영화관입장권 통합전산망에 따르면 영화 ‘스파이더맨: 브랜드 뉴 데이’는 26일 오전 10시 4분 기준 개봉을 3일 앞두고 사전 예매관객수 50만 559명을 기록하며 예매량 50만 장을 넘어섰다. 이는 지난 2022년 개봉해 천만 관객을 동원한 ‘아바타: 물의 길’이 개봉 3일 전 오후 11시 기준 사전 예매관객수 50만 541명을 넘은 속도보다 빠른 결과. 앞선 세 편의 시리즈가 모두 700만 관객을 돌파한 만큼, ‘스파이더맨: 브랜드 뉴 데이’가 새롭게 써 내려갈 흥행 기록에 뜨거운 관심이 모아지고 있다. ‘스파이더맨: 브랜드 뉴 데이’는 ‘스파이더맨: 노 웨이 홈’ 사건으로 모두에게 잊힌 ‘피터 파커’가 자신의 정체를 기억하는 의문의 적의 등장과 DNA 변이로 통제 불가능한 힘을 얻으며 더 깊은 혼란에 빠진 가운데, 소중한 이들을 지키기 위해 새로운 위협에 맞서는 액션 블록버스터로, 오는 29일 북미보다 빠르",
