      "summary": "‘스파이더맨: 브랜드 뉴 데이’가 사전 예매량이 50만장을 돌파하며 압도적인 티켓 파워를 입증했다. 26일 영화진흥위원회 영화관입장권 통합전산망에 영화 ‘스파이더맨: 브랜드 뉴 데이’(이하 ‘스파이더맨4’)는 개봉 사흘을 앞둔 이날 오전 10시 4분 기준 예매량 50만 559명, 예매율 59%를 기록했다. 이는 2022년 개봉해 천만 관객을 동원한 ‘아바타: 물의 길’보다 빠른 속도로, ‘스파이더맨4’의 강력한 흥행세를 예고한다. 특히 앞선 세 편의 ‘톰스파’ 시리즈가 모두 700만 관객을 돌파한 만큼, ‘스파이더맨4’가 새롭게 써 내려갈 흥행 기록에 뜨거운 관심이 모아지고 있다. ‘스파이더맨4’는 전편 ‘스파이더맨: 노 웨이 홈’ 사건으로 모두에게 잊힌 피터 파커(톰 홀랜드)가 자신의 정체를 기억하는 의문의 적의 등장과 DNA 변이로 통제 불가능한 힘을 얻으며 더 깊은 혼란에 빠진 가운데, 소중한 이들을 지키기 위해 새로운 위협에 맞서는 이야기로, 오는 29일 국내에서 개봉한다.",
