      "summary": "배우 박진우가 SBS 금토드라마 ‘김부장’ 종영 소감을 전했다. 박진우는 7월 25일 종영한 '김부장'에서 세탁소 임씨로 불리는 임호원 역을 맡아 호연을 펼쳤다. 9회와 10회에서는 세탁소 임씨의 든든한 조력자 면모가 빛났다. 김부장(소지섭 분), 성한수(최대훈 분), 박진철(윤경호 분), 정상아(손나은 분)가 리응령(이재용 분)을 탈취하는 일촉즉발의 작전 속에서 외부 동태를 실시간으로 살피며 극의 긴장감을 높였다. 임호원은 모든 사투가 끝난 후 새 출발을 앞둔 김부장 부녀에게 다린 양복을 선물하며 “새 출발할 땐 양복 한 벌쯤은 새로 뽑아 입으셔야죠. 양복은 쫙쫙 잘 다려 입어야 인생도 쭉쭉 펴지는 겁니다”라는 훈훈한 덕담을 건넸다. 두 사람이 비로소 정식으로 인사를 나누는 장면은 거친 여정을 함께 견뎌온 이들의 묵직한 신뢰와 아쉬움을 보여줬다. 박진우는 26일 오전 소속사를 통해 “역대급 시청률이라는 많은 분들의 엄청난 사랑에 떨리는 마음으로 한없이 감사하다는 말씀드리고 싶다.",
