      "summary": "시즌제 맛집 SBS가 또 하나의 시즌제 드라마를 탄생시킬 예정이다. 바로 2026년 최고의 드라마로 손꼽히는 ‘김부장’이다. 26일 OSEN 취재 결과, SBS 금토드라마 ‘김부장’(극본 남대중, 연출 이승영·이소은, 기획 스튜디오S, 제작 스튜디오S·판타지오)은 시즌2에 대한 논의를 시작했다. ‘김부장’은 1회 9.5%의 시청률로 산뜻하게 출발해 4회에 21.6%를 돌파하며 마의 20% 시청률을 넘겨버렸다. 최종회인 10회까지 7회 연속 20% 시청률을 돌파하며 전국 23.0% 시청률로 종영했다. 순간 최고 시청률은 27.1%다.(닐슨코리아 제공) 시작부터 흥행 기세를 이어갔던 ‘김부장’이기에 자연스럽게 시즌제에 대한 궁금증이 커질 수 밖에 없었다. 특히 소지섭도 SBS 드라마 미디어데이에 참석해 연기대상보다 ‘시즌제’ 드라마를 원한다고 밝힌 바 있다. 시즌1에서 네 아버지의 각기 다른 부성애를 보여줬던 ‘김부장’은 최종회에서 주강찬(주상욱 분)과 주학건설을 무너뜨린 김부장이 ‘백",
