      "summary": "방송인 붐 딸 29개월 윤서 양이 인형 같은 미모와 사랑스러운 먹방으로 시청자들의 시선을 사로잡았다. 24일 MBC 측은 \"인터넷 반응 휩쓴 아기들과 떠나는 등산 여행\"이라는 제목의 '최우수산' 예고편을 공개했다. 영상 속에는 장동민과 지우, 시우 남매, 허경환과 막내 조카 리아, 붐 딸 윤서와 함께 산행에 나서는 모습이 담겼다. 특히 이날 처음 모습을 드러낸 붐의 딸 윤서 양은 또렷한 이목구비와 커다란 눈망울, 인형을 연상케 하는 사랑스러운 비주얼로 단번에 시선을 사로잡았다. 간식을 먹는 모습은 귀여움을 한층 더했다. 한 손으로 음식을 꼭 쥔 채 오물오물 먹는 모습과 해맑은 미소는 보는 이들의 미소를 자아내며 '랜선 이모, 삼촌'들의 마음을 녹였다. 이에 제작진은 \"예고에 (윤서)나온 뒤 핫토픽에 올라왔다\"라고 하자, 붐은 \"처음이라서 그럴 거다. 윤서를 궁금해하시는 분들이 많았다\"라며 웃었다. 또한 허경환의 조카 리아 양은 삼촌의 대표 유행어를 따라 하는 것은 물론 음악에 맞춰",
