      "summary": "조니 뎁의 충격적인 비주얼 근황이 공개됐다. 조니 뎁은 7월 23일(현지시간) 미국 캘리포니아 샌디에이고에서 열린 코믹콘에 참석했다. 이날 조니 뎁은 영화 '스크루지: 크리스마스 캐럴'에서 맡은 역할인 스크루지로 완벽 변신, 충격적인 비주얼을 자랑했다. 올해 북미 개봉 예정인 '스크루지: 크리스마스 캐럴'은 조니 뎁이 전 부인 앰버 허드와의 2022년 재판 이후 첫 할리우드 대작 복귀작이어서 주목받고 있다. 조니 뎁은 극 중 악명 높은 크리스마스 심술쟁이 에벤에저 스크루지를 연기한다. 이에 심술궂은 스크루지로 분한 조니 뎁은 압도적인 분위기로 영화를 향한 기대감을 높인다. 한편, 조니 뎁은 전처 앰버 허드와의 길고도 공개적인 법정 공방을 이어왔다. 이들은 서로를 가정 폭력 혐의로 고소했고, 배심원단은 두 사람 모두 명예훼손 혐의 유죄 판결을 내렸다. 이 사건으로 인해 조니 뎁은 '해리 포터' 스핀오프 영화인 '신비한 동물들과 덤블도어의 비밀'에서 맡았던 악당 그린델왈드 역에서 하차했",
