      "summary": "'미션 임파서블', '스타트렉' 등 영화 팬들의 오랜 사랑을 받아온 배우 앙투아네트 바우어의 사망 비보가 뒤늦게 전해졌다. 향년 93세. 지난 14일(현지 시간) 피메일 퍼스트 등 현지 다수 매체는 앙투아네트 바우어의 부고 소식이 사망 세 달 만에 전해졌다고 일괄 보도했다. 부고를 처음 전한 절친에 따르면 고인은 지난 4월 30일 미국 로스앤젤레스 이글록 소재 요양시설에서 눈을 감았다. 1932년 독일에서 태어나 영국에서 성장한 고인은 배우로 전향하기 전 국제난민기구에서 근무하며 제2차 세계대전 피해자들을 지원하는 인도주의적 활동을 이어갔다. 1953년 캐나다로 이주한 뒤 캐나다방송협회에 입사해 대본 집필과 생방송 인터뷰 등 다양한 방송 업무를 경험한 뒤 본격적으로 연기의 길로 들어섰다. 바우어가 할리우드에 발을 들인 계기는 말론 브란도 주연 영화 '바운티호의 반란' 무크레디트 출연이었다. 이후 1960년대 인기 TV 시리즈 '스타트렉: 우주대작전'의 에피소드 'Catspaw'에서",
      "url": "https://m.entertain.naver.com/now/article/445/0000441270",
